import type { Plugin } from 'rollup';

function makeSafe(namespace: string): string
{
	return namespace.split('.').join('?.');
}

export function transformIifeLine(line: string): string | null
{
	// Match IIFE closing generated by Rollup with extend: true
	// Format: })(this.BX.NS = this.BX.NS || {}<optional globals>);
	// Rollup 4 uses single closing paren: })(own = own || {}, dep);
	// Rollup 3 used double closing paren: })(own = own || {}, dep));
	const match = /^\}\)\((this\.[.\w]+\s*=\s*[^|]+\|\|\s*\{\})(.*?)(\)+);$/.exec(line);
	if (!match)
	{
		return null;
	}

	const ownPart = match[1];
	const globalsRaw = match[2];
	const closingParens = match[3];

	// Own namespace stays unchanged — it's already safely initialized at the top of the bundle
	const parts = [ownPart];

	if (globalsRaw.length > 0)
	{
		// globalsRaw starts with ", " or ","
		const globals = globalsRaw.replace(/^,\s*/, '');

		if (globals.length > 0)
		{
			const safeGlobals = globals
				.split(',')
				.map((ns) => `${makeSafe(ns.trim())}??{}`)
				.join(', ');

			parts.push(safeGlobals);
		}
	}

	return `})(${parts.join(', ')}${closingParens};`;
}

export default function safeNamespacesPlugin(): Plugin
{
	return {
		name: 'safe-namespaces',

		renderChunk(code)
		{
			const lines = code.split('\n');

			for (let i = lines.length - 1; i >= 0; i--)
			{
				const transformed = transformIifeLine(lines[i]);
				if (transformed)
				{
					lines[i] = transformed;

					return { code: lines.join('\n'), map: null };
				}
			}

			return null;
		},
	};
}
